// Washer: switch-based hierarchical state machine generated by MachinaState.
// Do not edit by hand. Derive from this class and implement the guard and action hooks.
#pragma once

#include <cstddef>

namespace Appliances {

    class Washer {
      public:
        enum class State {
            Idle,
            Running,
            Washing,   // in Running
            Rinsing,   // in Running
            Spinning,   // in Running
            ProgramDone,   // in Running
            Heating,   // in Running
            Holding,   // in Running
            HeaterDone,   // in Running
            Error,
            None
        };

        enum class Event {
            Start,
            Spun,
            TempReached,
            TempDropped,
            SetTemp,
            Overheat,
            Cancel,
            Reset,
            QuickRinse,
            Washing_After30000ms,   // after(30000 ms) in Washing
            Rinsing_After20000ms,   // after(20000 ms) in Rinsing
            Completion   // internal: completion of a state
        };

        enum class TraceKind {
            Start,        // name = machine name
            Event,        // name = event being dispatched
            Ignored,      // name = event no state handled
            Transition,   // name = "Source -> Target"
            Exit,         // name = state being exited
            Enter         // name = state being entered
        };

        static constexpr std::size_t kStateCount  = 10;
        static constexpr std::size_t kEventCount  = 12;
        static constexpr std::size_t kRegionCount = 3;   // region 0 is the top level
        static constexpr std::size_t kTimerCount  = 2;

        virtual ~Washer() = default;

        // Resets the machine (running timers are cancelled, history is forgotten) and enters the initial state configuration.
        void Start() {
            if (timerArmed_[0]) {
                timerArmed_[0] = false;
                ++timerGeneration_[0];
                CancelTimer(Event::Washing_After30000ms);
            }
            if (timerArmed_[1]) {
                timerArmed_[1] = false;
                ++timerGeneration_[1];
                CancelTimer(Event::Rinsing_After20000ms);
            }
            for (State& state : active_) {
                state = State::None;
            }
            for (bool& flag : pending_) {
                flag = false;
            }
            Trace(TraceKind::Start, "Washer");
            EnterDown(State::None, State::Idle);
            RunCompletions();
        }

        // Dispatches an event to the innermost active states first. Returns false if the event was not handled.
        bool Dispatch(Event event) {
            switch (event) {
                case Event::SetTemp:
                case Event::Completion:
                    return false;   // use the typed Dispatch method / internal event
                default:
                    break;
            }
            args_ = nullptr;
            const bool handled = DispatchCore(event);
            args_ = nullptr;
            return handled;
        }

        bool DispatchSetTemp(int celsius) {
            const SetTempArgs args { celsius };
            args_ = &args;
            const bool handled = DispatchCore(Event::SetTemp);
            args_ = nullptr;
            return handled;
        }

        // Dispatches a timeout reported by a timer started with StartTimer; stale timeouts are ignored.
        bool DispatchTimeout(Event timeout, unsigned generation) {
            const int index = TimerIndex(timeout);
            if (index < 0 || !timerArmed_[index] || timerGeneration_[index] != generation) {
                return false;
            }
            args_ = nullptr;
            const bool handled = DispatchCore(timeout);
            args_ = nullptr;
            return handled;
        }

        // Innermost active state (following the first region of orthogonal states).
        State Current() const {
            return Innermost(active_[0]);
        }

        // True if the given state is active.
        bool IsIn(State state) const {
            return state != State::None && active_[RegionOf(state)] == state;
        }

        // True once a top-level final state has been reached.
        bool IsFinished() const {
            return false;
        }

        static State ParentOf(State state) {
            switch (state) {
                case State::Washing:
                case State::Rinsing:
                case State::Spinning:
                case State::ProgramDone:
                case State::Heating:
                case State::Holding:
                case State::HeaterDone:
                    return State::Running;
                default:
                    return State::None;
            }
        }

        static const char* StateName(State state) {
            switch (state) {
                case State::Idle:
                    return "Idle";
                case State::Running:
                    return "Running";
                case State::Washing:
                    return "Washing";
                case State::Rinsing:
                    return "Rinsing";
                case State::Spinning:
                    return "Spinning";
                case State::ProgramDone:
                    return "ProgramDone";
                case State::Heating:
                    return "Heating";
                case State::Holding:
                    return "Holding";
                case State::HeaterDone:
                    return "HeaterDone";
                case State::Error:
                    return "Error";
                default:
                    return "None";
            }
        }

        static const char* EventName(Event event) {
            switch (event) {
                case Event::Start:
                    return "Start";
                case Event::Spun:
                    return "Spun";
                case Event::TempReached:
                    return "TempReached";
                case Event::TempDropped:
                    return "TempDropped";
                case Event::SetTemp:
                    return "SetTemp";
                case Event::Overheat:
                    return "Overheat";
                case Event::Cancel:
                    return "Cancel";
                case Event::Reset:
                    return "Reset";
                case Event::QuickRinse:
                    return "QuickRinse";
                case Event::Washing_After30000ms:
                    return "Washing_After30000ms";
                case Event::Rinsing_After20000ms:
                    return "Rinsing_After20000ms";
                case Event::Completion:
                    return "Completion";
                default:
                    return "";
            }
        }

      protected:
        // Timers for after(...) transitions: when a timer elapses, call DispatchTimeout(timeout, generation).
        virtual void StartTimer(Event timeout, unsigned milliseconds, unsigned generation) = 0;
        virtual void CancelTimer(Event timeout)                                            = 0;
        // Override to log state machine activity.
        virtual void Trace(TraceKind kind, const char* name) {
            (void)kind;
            (void)name;
        }
        // Guards
        virtual bool isCool() = 0;
        // Actions
        virtual void lockDoor() = 0;
        virtual void unlockDoor() = 0;
        virtual void setTemperature() = 0;
        virtual void motorSlow() = 0;
        virtual void motorFast() = 0;
        virtual void motorStop() = 0;
        virtual void heaterOn() = 0;
        virtual void heaterOff() = 0;
        virtual void alarm() = 0;
        virtual void fillWater() = 0;
        virtual void beep() = 0;
        virtual void drain() = 0;
        virtual void adjust(int celsius) = 0;

      private:
        // Arguments of the event being dispatched; only valid during Dispatch.
        struct SetTempArgs {
            int celsius;
        };
        const SetTempArgs& ArgsOfSetTemp() const {
            return *static_cast<const SetTempArgs*>(args_);
        }

        const void* args_ = nullptr;

        bool DispatchCore(Event event) {
            const int timer = TimerIndex(event);
            if (timer >= 0) {
                timerArmed_[timer] = false;   // a timer fires once
            }
            exited_ = State::None;
            Trace(TraceKind::Event, EventName(event));
            if (active_[0] != State::None && DispatchState(active_[0], event)) {
                RunCompletions();
                return true;
            }
            Trace(TraceKind::Ignored, EventName(event));
            return false;
        }

        // Offers the event to every active region below `state` first, then to `state` itself.
        bool DispatchState(State state, Event event) {
            bool handled = false;
            const std::size_t first = FirstRegionOf(state);
            for (std::size_t region = first; region < first + RegionsOf(state); ++region) {
                if (active_[region] != State::None && DispatchState(active_[region], event)) {
                    handled = true;
                    // Stop if the transition exited `state`, even if it entered it again.
                    for (State s = state; s != State::None; s = ParentOf(s)) {
                        if (s == exited_) {
                            return true;
                        }
                    }
                }
            }
            return handled || HandleEvent(state, event);
        }

        // Completion transitions fire once a state is entered, or a composite state has reached final states in all regions.
        void RunCompletions() {
            for (;;) {
                std::size_t index = 0;
                while (index < kStateCount && !pending_[index]) {
                    ++index;
                }
                if (index == kStateCount) {
                    return;
                }
                pending_[index]   = false;
                const State state = static_cast<State>(index);
                if (active_[RegionOf(state)] == state) {
                    HandleEvent(state, Event::Completion);
                }
            }
        }

        void MarkCompletion(State state) {
            switch (state) {
                case State::ProgramDone:
                    if (AllRegionsFinal(State::Running))
                        pending_[1] = true;   // Running
                    break;
                case State::HeaterDone:
                    if (AllRegionsFinal(State::Running))
                        pending_[1] = true;   // Running
                    break;
                default:
                    break;
            }
        }

        bool AllRegionsFinal(State state) const {
            const std::size_t first = FirstRegionOf(state);
            for (std::size_t region = first; region < first + RegionsOf(state); ++region) {
                if (!IsFinalState(active_[region])) {
                    return false;
                }
            }
            return true;
        }

        void StartTimers(State state) {
            switch (state) {
                case State::Washing:
                    ++timerGeneration_[0];
                    timerArmed_[0] = true;
                    StartTimer(Event::Washing_After30000ms, 30000u, timerGeneration_[0]);
                    break;
                case State::Rinsing:
                    ++timerGeneration_[1];
                    timerArmed_[1] = true;
                    StartTimer(Event::Rinsing_After20000ms, 20000u, timerGeneration_[1]);
                    break;
                default:
                    break;
            }
        }

        void CancelTimers(State state) {
            switch (state) {
                case State::Washing:
                    timerArmed_[0] = false;
                    CancelTimer(Event::Washing_After30000ms);
                    break;
                case State::Rinsing:
                    timerArmed_[1] = false;
                    CancelTimer(Event::Rinsing_After20000ms);
                    break;
                default:
                    break;
            }
        }

        static int TimerIndex(Event event) {
            switch (event) {
                case Event::Washing_After30000ms:
                    return 0;
                case Event::Rinsing_After20000ms:
                    return 1;
                default:
                    return -1;
            }
        }

        bool HandleEvent(State state, Event event) {
            switch (state) {
                case State::Idle:
                    switch (event) {
                        case Event::Start:
                            Trace(TraceKind::Transition, "Idle -> Running");
                            ExitState(State::Idle);
                            fillWater();
                            EnterDown(State::None, State::Running);
                            return true;
                        case Event::QuickRinse:
                            Trace(TraceKind::Transition, "Idle -> Rinsing");
                            ExitState(State::Idle);
                            EnterDown(State::None, State::Rinsing);
                            return true;
                        default:
                            break;
                    }
                    break;
                case State::Running:
                    switch (event) {
                        case Event::Cancel:
                            Trace(TraceKind::Transition, "Running -> Idle");
                            ExitState(State::Running);
                            drain();
                            EnterDown(State::None, State::Idle);
                            return true;
                        case Event::Completion:
                            Trace(TraceKind::Transition, "Running -> Idle");
                            ExitState(State::Running);
                            beep();
                            EnterDown(State::None, State::Idle);
                            return true;
                        default:
                            break;
                    }
                    break;
                case State::Washing:
                    switch (event) {
                        case Event::Washing_After30000ms:
                            Trace(TraceKind::Transition, "Washing -> Rinsing");
                            ExitState(State::Washing);
                            drain();
                            EnterDown(State::Running, State::Rinsing);
                            return true;
                        default:
                            break;
                    }
                    break;
                case State::Rinsing:
                    switch (event) {
                        case Event::Rinsing_After20000ms:
                            Trace(TraceKind::Transition, "Rinsing -> Spinning");
                            ExitState(State::Rinsing);
                            EnterDown(State::Running, State::Spinning);
                            return true;
                        default:
                            break;
                    }
                    break;
                case State::Spinning:
                    switch (event) {
                        case Event::Spun:
                            Trace(TraceKind::Transition, "Spinning -> ProgramDone");
                            ExitState(State::Spinning);
                            EnterDown(State::Running, State::ProgramDone);
                            return true;
                        default:
                            break;
                    }
                    break;
                case State::Heating:
                    switch (event) {
                        case Event::TempReached:
                            Trace(TraceKind::Transition, "Heating -> Holding");
                            ExitState(State::Heating);
                            EnterDown(State::Running, State::Holding);
                            return true;
                        case Event::Overheat:
                            Trace(TraceKind::Transition, "Heating -> Error");
                            ExitState(State::Running);
                            EnterDown(State::None, State::Error);
                            return true;
                        default:
                            break;
                    }
                    break;
                case State::Holding:
                    switch (event) {
                        case Event::Spun:
                            Trace(TraceKind::Transition, "Holding -> HeaterDone");
                            ExitState(State::Holding);
                            EnterDown(State::Running, State::HeaterDone);
                            return true;
                        case Event::TempDropped:
                            Trace(TraceKind::Transition, "Holding -> Heating");
                            ExitState(State::Holding);
                            EnterDown(State::Running, State::Heating);
                            return true;
                        case Event::SetTemp:
                            Trace(TraceKind::Transition, "Holding (internal)");
                            adjust(ArgsOfSetTemp().celsius);
                            return true;
                        default:
                            break;
                    }
                    break;
                case State::Error:
                    switch (event) {
                        case Event::Reset:
                            if (isCool()) {
                                Trace(TraceKind::Transition, "Error -> Idle");
                                ExitState(State::Error);
                                EnterDown(State::None, State::Idle);
                                return true;
                            }
                            break;
                        default:
                            break;
                    }
                    break;
                default:
                    break;
            }
            return false;
        }

        static std::size_t RegionOf(State state) {
            switch (state) {
                case State::Washing:
                case State::Rinsing:
                case State::Spinning:
                case State::ProgramDone:
                    return 1;
                case State::Heating:
                case State::Holding:
                case State::HeaterDone:
                    return 2;
                default:
                    return 0;
            }
        }

        static std::size_t FirstRegionOf(State state) {
            switch (state) {
                case State::Running:
                    return 1;
                default:
                    return 0;
            }
        }

        static std::size_t RegionsOf(State state) {
            switch (state) {
                case State::Running:
                    return 2;
                default:
                    return 0;
            }
        }

        static bool IsFinalState(State state) {
            switch (state) {
                case State::ProgramDone:
                case State::HeaterDone:
                    return true;
                default:
                    return false;
            }
        }

        void EnterRegion(std::size_t region) {
            switch (region) {
                case 1:
                    EnterDown(State::Running, State::Washing);
                    break;
                case 2:
                    setTemperature();
                    EnterDown(State::Running, State::Heating);
                    break;
                default:
                    break;
            }
        }

        void OnEntry(State state) {
            switch (state) {
                case State::Running:
                    lockDoor();
                    break;
                case State::Washing:
                    motorSlow();
                    break;
                case State::Spinning:
                    motorFast();
                    break;
                case State::Heating:
                    heaterOn();
                    break;
                case State::Error:
                    alarm();
                    break;
                default:
                    break;
            }
        }

        void OnExit(State state) {
            switch (state) {
                case State::Running:
                    unlockDoor();
                    break;
                case State::Spinning:
                    motorStop();
                    break;
                case State::Heating:
                    heaterOff();
                    break;
                default:
                    break;
            }
        }

        void ExitState(State state) {
            const std::size_t first = FirstRegionOf(state);
            for (std::size_t region = first + RegionsOf(state); region-- > first;) {
                if (active_[region] != State::None) {
                    ExitState(active_[region]);
                }
            }
            Trace(TraceKind::Exit, StateName(state));
            CancelTimers(state);
            OnExit(state);
            active_[RegionOf(state)] = State::None;
            exited_ = state;
        }

        // Enters every state from below `from` down to `target`, then follows default (initial) transitions
        // below `target`.
        void EnterDown(State from, State target) {
            State state = target;
            State next  = State::None;
            while (ParentOf(state) != from) {
                next  = state;
                state = ParentOf(state);
            }
            EnterState(state);
            if (next == State::None) {
                EnterDefault(state);
                return;
            }
            const std::size_t first = FirstRegionOf(state);
            for (std::size_t region = first; region < first + RegionsOf(state); ++region) {
                if (region == RegionOf(next)) {
                    EnterDown(state, target);
                } else {
                    EnterRegion(region);
                }
            }
        }

        void EnterState(State state) {
            active_[RegionOf(state)] = state;
            Trace(TraceKind::Enter, StateName(state));
            OnEntry(state);
            StartTimers(state);
        }

        void EnterDefault(State state) {
            const std::size_t first = FirstRegionOf(state);
            for (std::size_t region = first; region < first + RegionsOf(state); ++region) {
                EnterRegion(region);
            }
            if (RegionsOf(state) == 0) {
                MarkCompletion(state);
            }
        }

        State Innermost(State state) const {
            while (state != State::None && RegionsOf(state) > 0 && active_[FirstRegionOf(state)] != State::None) {
                state = active_[FirstRegionOf(state)];
            }
            return state;
        }

        State active_[kRegionCount] = { State::None, State::None, State::None };   // active state per region
        State exited_ = State::None;   // outermost state exited by the latest transition
        bool pending_[kStateCount] = {};   // completion events not yet processed
        unsigned timerGeneration_[kTimerCount] = {};
        bool timerArmed_[kTimerCount] = {};
    };
}
